import clsx from 'clsx';
import { useContext } from '@wordpress/element';
import { __, sprintf } from '@wordpress/i18n';
import { inertValue } from '@wordpress/react-inert-value';
import { __unstableGetBlockProps as getBlockProps } from '@wordpress/blocks';
import { useMergeRefs, useDisabled, useRefEffect } from '@wordpress/compose';
import { useDispatch } from '@wordpress/data';
import warning from '@wordpress/warning';
import type { Block } from '@wordpress/blocks';
import useMovingAnimation from '../../use-moving-animation';
import { store as blockEditorStore } from '../../../store';
import { PrivateBlockContext } from '../private-block-context';
import { useFocusFirstElement } from './use-focus-first-element';
import { useIsHovered } from './use-is-hovered';
import {
	blockBindingsKey,
	useBlockEditContext,
} from '../../block-edit/context';
import { useFocusHandler } from './use-focus-handler';
import { useRegisterBlockEventHandlers } from './use-register-block-event-handlers';
import { useEventHandlers } from './use-selected-block-event-handlers';
import { useBlockRefProvider } from './use-block-refs';
import { useIntersectionObserver } from './use-intersection-observer';
import { useScrollIntoView } from './use-scroll-into-view';
import { useFlashEditableBlocks } from '../../use-flash-editable-blocks';
import { useFirefoxDraggableCompatibility } from './use-firefox-draggable-compatibility';
import type {
	UseBlockPropsOptions,
	UseBlockPropsProps,
	UseBlockPropsResult,
	PrivateBlockContextValue,
} from '../types';

/**
 * Returns a ref that inserts a ghost block when the user enters it: the
 * same block object the ghost has rendered from all along, so nothing
 * about the element changes. Native listeners, so blocks' own handlers
 * are never clashed with.
 *
 * @param rootClientId The block's root client ID.
 * @param ghostBlock   The ghost block object, while not inserted.
 *
 * @return Ref effect for the block element.
 */
function useGhostMaterialize(
	rootClientId: string | null | undefined,
	ghostBlock: Block | undefined
) {
	const { insertBlocks } = useDispatch( blockEditorStore );

	return useRefEffect< HTMLElement >(
		( element ) => {
			if ( ! ghostBlock ) {
				return;
			}
			function remove() {
				element.removeEventListener( 'pointerdown', materialize, true );
				element.removeEventListener( 'focusin', materialize, true );
			}
			function materialize() {
				// One gesture fires both events; insert once.
				remove();
				// Update the selection: the ghost is empty, so the caret
				// can only be at its start, and the undo level records it.
				insertBlocks(
					// The listeners are only added for a ghost block.
					[ ghostBlock! ],
					undefined,
					rootClientId,
					true,
					0
				);
			}
			element.addEventListener( 'pointerdown', materialize, true );
			element.addEventListener( 'focusin', materialize, true );
			return remove;
		},
		[ ghostBlock, rootClientId, insertBlocks ]
	);
}

/**
 * This hook is used to lightly mark an element as a block element. The element
 * should be the outermost element of a block. Call this hook and pass the
 * returned props to the element to mark as a block. If you define a ref for the
 * element, it is important to pass the ref to this hook, which the hook in turn
 * will pass to the component through the props it returns. Optionally, you can
 * also pass any other props through this hook, and they will be merged and
 * returned.
 *
 * Use of this hook on the outermost element of a block is required if using API >= v2.
 *
 * @example
 * ```js
 * import { useBlockProps } from '@wordpress/block-editor';
 *
 * export default function Edit() {
 *
 *   const blockProps = useBlockProps( {
 *     className: 'my-custom-class',
 *     style: {
 *       color: '#222222',
 *       backgroundColor: '#eeeeee'
 *     }
 *   } )
 *
 *   return (
 *	    <div { ...blockProps }>
 *
 *     </div>
 *   )
 * }
 *
 * ```
 *
 *
 * @param {Object}  props                    Optional. Props to pass to the element. Must contain
 *                                           the ref if one is defined.
 * @param {Object}  options                  Options for internal use only.
 * @param {boolean} options.__unstableIsHtml
 *
 * @return {Object} Props to pass to the element to mark as a block.
 */
export function useBlockProps<
	P extends UseBlockPropsProps = UseBlockPropsProps,
>(
	// Generic, so inline props of any element are not excess properties.
	props: P | Record< string, never > = {},
	{ __unstableIsHtml }: UseBlockPropsOptions = {}
): UseBlockPropsResult {
	const {
		clientId,
		className,
		wrapperProps = {},
		isAligned,
		index,
		mode,
		name,
		blockApiVersion,
		blockTitle,
		isSelected,
		isSubtreeDisabled,
		hasOverlay,
		initialPosition,
		blockEditingMode,
		isHighlighted,
		isMultiSelected,
		isPartiallySelected,
		isReusable,
		isDragging,
		hasChildSelected,
		isEditingDisabled,
		hasEditableOutline,
		isEditingContentOnlySection,
		defaultClassName,
		isSectionBlock,
		isWithinSectionBlock,
		canMove,
		isBlockCurrentlyHidden,
		ariaLabel,
		ghostBlock,
		rootClientId,
		// A block list block provides the context, with its client ID.
	} = useContext( PrivateBlockContext ) as PrivateBlockContextValue & {
		clientId: string;
	};
	const ghostRef = useGhostMaterialize( rootClientId, ghostBlock );

	useRegisterBlockEventHandlers( clientId, wrapperProps );

	const blockLabel = sprintf(
		// translators: %s: Type of block (i.e. Text, Image etc)
		__( 'Block: %s' ),
		// Block types have a title.
		blockTitle as string
	);
	const htmlSuffix = mode === 'html' && ! __unstableIsHtml ? '-visual' : '';
	const ffDragRef = useFirefoxDraggableCompatibility();
	const isHoverEnabled = ! isWithinSectionBlock;
	const mergedRefs = useMergeRefs< HTMLElement >( [
		props.ref,
		ghostRef,
		useFocusFirstElement( { clientId, initialPosition } ),
		useBlockRefProvider( clientId ),
		useFocusHandler( clientId ),
		useEventHandlers( { clientId, isSelected, isMultiSelected } ),
		useIsHovered( { isEnabled: isHoverEnabled } ),
		useIntersectionObserver(),
		useMovingAnimation( { triggerAnimationOnChange: index, clientId } ),
		useDisabled( { isDisabled: ! hasOverlay } ),
		useFlashEditableBlocks( {
			clientId,
			isEnabled: isSectionBlock,
		} ),
		useScrollIntoView( { isSelected } ),
		canMove ? ffDragRef : undefined,
	] );

	const blockEditContext = useBlockEditContext();
	const hasBlockBindings = !! blockEditContext[ blockBindingsKey ];
	const bindingsStyle = hasBlockBindings
		? {
				'--wp-admin-theme-color': 'var(--wp-block-synced-color)',
				'--wp-admin-theme-color--rgb':
					'var(--wp-block-synced-color--rgb)',
			}
		: {};

	// Ensures it warns only inside the `edit` implementation for the block.
	// A missing version compares false.
	if (
		( blockApiVersion as number ) < 2 &&
		clientId === blockEditContext.clientId
	) {
		warning(
			`Block type "${ name }" must support API version 2 or higher to work correctly with "useBlockProps" method.`
		);
	}

	let hasNegativeMargin = false;
	if (
		// @ts-expect-error Bug: a numeric margin has no `charAt`, so this throws.
		wrapperProps?.style?.marginTop?.charAt( 0 ) === '-' ||
		// @ts-expect-error Bug: a numeric margin has no `charAt`, so this throws.
		wrapperProps?.style?.marginBottom?.charAt( 0 ) === '-' ||
		// @ts-expect-error Bug: a numeric margin has no `charAt`, so this throws.
		wrapperProps?.style?.marginLeft?.charAt( 0 ) === '-' ||
		// @ts-expect-error Bug: a numeric margin has no `charAt`, so this throws.
		wrapperProps?.style?.marginRight?.charAt( 0 ) === '-'
	) {
		hasNegativeMargin = true;
	}

	return {
		tabIndex: blockEditingMode === 'disabled' ? -1 : 0,
		draggable: canMove && ! hasChildSelected ? true : undefined,
		...wrapperProps,
		...props,
		ref: mergedRefs,
		id: `block-${ clientId }${ htmlSuffix }`,
		role: 'document',
		'aria-label':
			ariaLabel ??
			( clientId === ghostBlock?.clientId
				? __( 'Add default block' )
				: undefined ) ??
			props[ 'aria-label' ] ??
			blockLabel,
		'data-block': clientId,
		'data-type': name,
		'data-title': blockTitle,
		inert: inertValue( isSubtreeDisabled ),
		className: clsx(
			'block-editor-block-list__block',
			{
				// The wp-block className is important for editor styles.
				'wp-block': ! isAligned,
				'has-block-overlay': hasOverlay,
				'is-selected': isSelected,
				'is-highlighted': isHighlighted,
				'is-multi-selected': isMultiSelected,
				'is-movable-multi-selected': isMultiSelected && canMove,
				'is-partially-selected': isPartiallySelected,
				'is-reusable': isReusable,
				'is-dragging': isDragging,
				'has-child-selected': hasChildSelected,
				'is-editing-disabled': isEditingDisabled,
				'has-editable-outline': hasEditableOutline,
				'has-negative-margin': hasNegativeMargin,
				'is-editing-content-only-section': isEditingContentOnlySection,
				'is-block-hidden': isBlockCurrentlyHidden,
			},
			className,
			props.className,
			wrapperProps.className,
			defaultClassName
		),
		style: { ...wrapperProps.style, ...props.style, ...bindingsStyle },
	};
}

/**
 * Call within a save function to get the props for the block wrapper.
 *
 * @param {Object} props Optional. Props to pass to the element.
 */
useBlockProps.save = getBlockProps;
